UPDATE equipment_run_time SET stop_reason = CASE
  WHEN id % 100 < 45 THEN '设备故障'
  WHEN id % 100 < 67 THEN '换型调机'
  WHEN id % 100 < 80 THEN '缺料待料'
  WHEN id % 100 < 88 THEN '计划保养'
  WHEN id % 100 < 93 THEN '品质异常停线'
  WHEN id % 100 < 97 THEN '程序参数异常'
  WHEN id % 100 < 99 THEN '人员待岗'
  ELSE '其他' END
WHERE stop_reason IS NULL AND stop_min > 0;

UPDATE station_detail SET wo_no =
  'WO-' || substr(product_model, 1, 1) || '-' || substr(record_date, 6, 2)
  || substr(record_date, 9, 2)
WHERE wo_no IS NULL;
